import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("nested pools", () => {
  test("nested pools", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
    await ui.setSetting(pg_uma, "pot", "100.00");
    expect(await ui.addPool(pg_uma, "Top")).toBe(true);
    expect(await ui.addPool(pg_uma, "Mid")).toBe(true);
    expect(await ui.addPool(pg_uma, "Low")).toBe(true);
    expect(await ui.addPool(pg_uma, "Deep")).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "Top", {"member": "Ada", "share": "70.00"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "Top", {"member": "pool:Mid", "share": "30.00"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "Mid", {"member": "Ben", "share": "50.00"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "Mid", {"member": "pool:Low", "share": "50.00"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "Low", {"member": "Cam", "share": "100.00"})).toBe(true);
    expect(await ui.addPoolMember(pg_uma, "Low", {"member": "pool:Top", "share": "1.00"})).toBe(false);
    expect(await ui.addPoolMember(pg_uma, "Low", {"member": "pool:Deep", "share": "1.00"})).toBe(false);
    expect(await ui.addPoolMember(pg_uma, "Deep", {"member": "pool:Mid", "share": "1.00"})).toBe(false);
    expect(await ui.addPoolMember(pg_uma, "Top", {"member": "pool:Mid", "share": "1.00"})).toBe(false);
    expect(await ui.addPoolMember(pg_uma, "Top", {"member": "pool:Top", "share": "1.00"})).toBe(false);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("pool-row-Top").getByTestId("pool-total-share")).toHaveText("100.00");
    await expect(pg_uma.getByTestId("pool-row-Top").getByTestId("pool-balanced")).toHaveText("yes");
    await expect(pg_uma.getByTestId("pool-member-Top-" + p_ada).getByTestId("pool-share")).toHaveText("70.00");
    await expect(pg_uma.getByTestId("pool-member-Top-" + p_ada).getByTestId("pool-cut")).toHaveText("70.00");
    await expect(pg_uma.getByTestId("pool-member-Top-pool-Mid").getByTestId("pool-share")).toHaveText("30.00");
    await expect(pg_uma.getByTestId("pool-member-Top-pool-Mid").getByTestId("pool-cut")).toHaveText("30.00");
    await expect(pg_uma.getByTestId("pool-row-Mid").getByTestId("pool-total-share")).toHaveText("100.00");
